ruleToc.chapterList:
@js:
let list=[];
//获取(接口)线路名
let jiekou=java.getString("$.player_info[*].show").split('\n').map(jk=> { //接口块，同线路
return {"n":jk,"V":1}
}
);
//this.java.log('🍊'+Date.now()+'🍊'+jiekou);
//获取集数
let jishu = String(java.getString("$.playlist")).split('$$$').map(xl=>{ //线路块
	xl = xl.split('#').map(js=>{ //集数块
		js = js.split('$');
        return {"n":js[0],"u":js[1],"V":false}
       });
		return xl;
	}
);
for (let i=0; i<jiekou.length;i++) {
    list.push(jiekou[i]);
    list=list.concat(jishu[i]);
}
//this.java.log('🍊'+Date.now()+'🍊'+JSON.stringify(list));
list
